    if (endpoint === "health")
    {
      if (request.method !== "GET")
      {
        SendRestError(response, 405, "method_not_allowed", "method not allowed");
        return;
      }

      HandleHealth(context, response);
      return;
    }

    if (endpoint === "models")
    {
