import { access, realpath } from "node:fs/promises";
import path from "node:path";

import { PathEscapeError } from "./errors.js";

export interface ResolveInputPathOptions
{
  allowMissing?: boolean;
}

export interface RootPolicy
{
  readonly rootDirectory: string;
  readonly canonicalRoot: string;
  ResolveInputPath(inputPath: string, options?: ResolveInputPathOptions): Promise<string>;
  ToRootRelativePath(absolutePath: string): string;
  AssertWithinRoot(absolutePath: string): void;
}

function NormalizeSeparators(inputPath: string): string
{
  return inputPath.replace(/\\/g, "/");
}

function HasParentTraversal(inputPath: string): boolean
{
  const segments = NormalizeSeparators(inputPath).split("/");

  for (const segment of segments)
  {
    if (segment === "..")
    {
      return true;
    }
  }

  return false;
}

function IsWithinRoot(candidate: string, canonicalRoot: string): boolean
{
  const relative = path.relative(canonicalRoot, candidate);

  if (relative === "")
  {
    return true;
  }

  if (relative.startsWith("..") || path.isAbsolute(relative))
  {
    return false;
  }

  return true;
}

export async function CreateRootPolicy(rootDirectory: string): Promise<RootPolicy>
{
  const canonicalRoot = await realpath(path.resolve(rootDirectory));

  function AssertWithinRoot(absolutePath: string): void
  {
    const normalized = path.resolve(absolutePath);

    if (!IsWithinRoot(normalized, canonicalRoot))
    {
      throw new PathEscapeError(
        "Path is outside the session root",
        normalized,
        "resolved_path_outside_root",
      );
    }
  }

  function ToRootRelativePath(absolutePath: string): string
  {
    const normalized = path.resolve(absolutePath);
    const relative = path.relative(canonicalRoot, normalized);

    if (relative === "" || relative === ".")
    {
      return ".";
    }

    if (relative.startsWith("..") || path.isAbsolute(relative))
    {
      throw new PathEscapeError(
        "Path is outside the session root",
        absolutePath,
        "resolved_path_outside_root",
      );
    }

    return relative.split(path.sep).join("/");
  }

  async function ResolveMissingWithinRoot(candidate: string): Promise<string>
  {
    AssertWithinRoot(candidate);

    let existingAncestor = canonicalRoot;
    let checkPath = candidate;
    const missingSegments: string[] = [];

    while (checkPath !== canonicalRoot && checkPath.length > canonicalRoot.length)
    {
      try
      {
        await access(checkPath);
        existingAncestor = await realpath(checkPath);
        AssertWithinRoot(existingAncestor);
        break;
      }
      catch
      {
        missingSegments.unshift(path.basename(checkPath));
        checkPath = path.dirname(checkPath);
      }
    }

    let resolved = existingAncestor;

    for (const segment of missingSegments)
    {
      resolved = path.join(resolved, segment);
      AssertWithinRoot(resolved);
    }

    return resolved;
  }

  async function ResolveInputPath(
    inputPath: string,
    options?: ResolveInputPathOptions,
  ): Promise<string>
  {
    if (!inputPath || inputPath.includes("\0"))
    {
      throw new PathEscapeError(
        "Path is outside the session root",
        inputPath,
        "invalid_path",
      );
    }

    const trimmed = inputPath.trim();

    if (trimmed.length === 0)
    {
      throw new PathEscapeError(
        "Path is outside the session root",
        inputPath,
        "empty_path",
      );
    }

    if (HasParentTraversal(trimmed))
    {
      throw new PathEscapeError(
        "Path is outside the session root",
        inputPath,
        "parent_traversal",
      );
    }

    const normalizedInput = NormalizeSeparators(trimmed);
    let candidate: string;

    if (path.isAbsolute(normalizedInput))
    {
      candidate = path.resolve(normalizedInput);
    }
    else
    {
      candidate = path.resolve(canonicalRoot, normalizedInput);
    }

    if (!IsWithinRoot(candidate, canonicalRoot))
    {
      throw new PathEscapeError(
        "Path is outside the session root",
        inputPath,
        "outside_root",
      );
    }

    if (options?.allowMissing)
    {
      return ResolveMissingWithinRoot(candidate);
    }

    const resolved = await realpath(candidate);
    AssertWithinRoot(resolved);
    return resolved;
  }

  return {
    rootDirectory: canonicalRoot,
    canonicalRoot,
    ResolveInputPath,
    ToRootRelativePath,
    AssertWithinRoot,
  };
}

import { constants } from "node:fs";
import { access, readFile } from "node:fs/promises";

import { Type } from "typebox";

import { RelativizeDisplayPath } from "../results.js";
import type { ScopedToolContext, ScopedToolDefinition } from "../types.js";
import {
  FormatNumberedLines,
  HandlePathEscape,
  ResolveScopedPath,
  ToolError,
  ToolSuccess,
  TruncateTextHead,
} from "../toolHelpers.js";

const x_readSchema = Type.Object({
  path: Type.String({ description: "Path to the file to read (relative or absolute)" }),
  offset: Type.Optional(Type.Number({ description: "Line number to start reading from (1-indexed)" })),
  limit: Type.Optional(Type.Number({ description: "Maximum number of lines to read" })),
});

function IsBinaryBuffer(buffer: Buffer): boolean
{
  const sample = buffer.subarray(0, Math.min(buffer.length, 8192));

  for (const byte of sample)
  {
    if (byte === 0)
    {
      return true;
    }
  }

  return false;
}

export function CreateReadTool(context: ScopedToolContext): ScopedToolDefinition
{
  return {
    name: "read",
    label: "read",
    description:
      "Read the contents of a UTF-8 text file under the session root. Output is line-numbered and truncated to 2000 lines or 50KB. Use offset/limit for large files.",
    parameters: x_readSchema,
    async execute(_toolCallId, params, signal)
    {
      const pathArg = String(params.path ?? "");
      const offset = typeof params.offset === "number" ? params.offset : undefined;
      const limit = typeof params.limit === "number" ? params.limit : undefined;

      if (signal?.aborted)
      {
        return ToolError("Operation aborted");
      }

      let absolutePath: string;

      try
      {
        absolutePath = await ResolveScopedPath(context.policy, pathArg);
      }
      catch (error)
      {
        const escapeResult = HandlePathEscape(context, "read", error);

        if (escapeResult)
        {
          return escapeResult;
        }

        throw error;
      }

      const displayPath = RelativizeDisplayPath(context.policy, absolutePath);

      try
      {
        await access(absolutePath, constants.R_OK);
      }
      catch
      {
        return ToolError(`Could not read file: ${displayPath}`);
      }

      const buffer = await readFile(absolutePath);

      if (IsBinaryBuffer(buffer))
      {
        return ToolError(`File is not UTF-8 text: ${displayPath}`);
      }

      const textContent = buffer.toString("utf-8");
      const allLines = textContent.split("\n");
      const startLine = offset ? Math.max(0, offset - 1) : 0;

      if (startLine >= allLines.length)
      {
        return ToolError(
          `Offset ${offset} is beyond end of file (${allLines.length} lines total)`,
        );
      }

      let selectedLines: string[];

      if (limit !== undefined)
      {
        const endLine = Math.min(startLine + limit, allLines.length);
        selectedLines = allLines.slice(startLine, endLine);
      }
      else
      {
        selectedLines = allLines.slice(startLine);
      }

      const joined = selectedLines.join("\n");
      const truncation = TruncateTextHead(joined);
      const numbered = FormatNumberedLines(
        truncation.content.split("\n"),
        startLine + 1,
      );

      let output = `${displayPath}\n${numbered}`;

      if (truncation.truncated)
      {
        const nextOffset = startLine + truncation.outputLines + 1;
        output += `\n\n[Showing lines ${startLine + 1}-${startLine + truncation.outputLines} of ${allLines.length}. Use offset=${nextOffset} to continue.]`;
      }
      else if (limit !== undefined && startLine + selectedLines.length < allLines.length)
      {
        const nextOffset = startLine + selectedLines.length + 1;
        const remaining = allLines.length - (startLine + selectedLines.length);
        output += `\n\n[${remaining} more lines in file. Use offset=${nextOffset} to continue.]`;
      }

      return ToolSuccess(output, {
        path: displayPath,
        totalLines: allLines.length,
        truncated: truncation.truncated,
      });
    },
  };
}

import { randomUUID } from "node:crypto";
import { performance } from "node:perf_hooks";

import type { WebSocket } from "ws";
import { WebSocket as WebSocketStatic } from "ws";

import type { AgentManager } from "../agents/manager.js";
import {
  FormatSessionKey,
  type SessionKey,
} from "../agents/lifecycle.js";
import {
  eventsToSnapshots,
  mapUserMessageToAgui,
} from "../agui/index.js";
import type { AguiEvent } from "../agui/types.js";
import {
  IsStreamProfilerEnabled,
  ProfileStreamPoint,
} from "../server/streamProfiler.js";
import type { ChatEnvelope } from "../shared/envelope.js";
import type { HistoryPageRequest } from "../shared/types.js";
import { ReadHistoryPage } from "../storage/history.js";
import type { StoragePaths } from "../storage/paths.js";
import { CollectSessionLogEntries } from "../storage/sessionLog.js";

import {
  CreateChatEnvelope,
  x_aguiEventKind,
  x_chatUserMessageKind,
  x_historyPageKind,
} from "./envelopes.js";
import type { ClientHistoryRequestPayload, ClientUserMessagePayload } from "./clientFrames.js";
import type { HistoryWindow, SessionPersistenceHub } from "./sessionPersistenceHub.js";

export interface ConnectedClient
{
  connectionId: string;
  clientId?: string;
  socket: WebSocket;
  lastAckSequence?: number;
}

export interface SessionBroadcasterOptions
{
  key: SessionKey;
  storagePaths: StoragePaths;
  agentManager: AgentManager;
  persistenceHub: SessionPersistenceHub;
}

function SendEnvelope(socket: WebSocket, envelope: ChatEnvelope): void
{
  if (socket.readyState === WebSocketStatic.OPEN)
  {
    const startedAt = performance.now();
    socket.send(JSON.stringify(envelope));

    if (IsStreamProfilerEnabled())
    {
      ProfileStreamPoint("websocket_send_called", {
        kind: envelope.kind,
        sequence: envelope.sequence,
        bufferedAmount: socket.bufferedAmount,
        sendCallMs: Math.round((performance.now() - startedAt) * 1000) / 1000,
      });
    }
  }
}

function ExtractAguiEvents(envelopes: ChatEnvelope[]): AguiEvent[]
{
  const messageIdsWithStoredAguiEvents = new Set<string>();
  const events: AguiEvent[] = [];

  for (const envelope of envelopes)
  {
    if (envelope.kind !== x_aguiEventKind || envelope.payload === undefined)
    {
      continue;
    }

    if (typeof envelope.payload !== "object" || envelope.payload === null)
    {
      continue;
    }

    const messageId = (envelope.payload as { messageId?: unknown }).messageId;

    if (typeof messageId === "string")
    {
      messageIdsWithStoredAguiEvents.add(messageId);
    }
  }

  for (const envelope of envelopes)
  {
    if (envelope.kind === x_aguiEventKind && envelope.payload !== undefined)
    {
      if (typeof envelope.payload === "object" && envelope.payload !== null)
      {
        events.push(envelope.payload as AguiEvent);
      }

      continue;
    }

    if (envelope.kind === x_chatUserMessageKind && envelope.payload !== undefined)
    {
      const payload = envelope.payload as { messageId?: string; text?: string };

      if (typeof payload.messageId === "string" && typeof payload.text === "string")
      {
        if (messageIdsWithStoredAguiEvents.has(payload.messageId))
        {
          continue;
        }

        events.push(...mapUserMessageToAgui({
          messageId: payload.messageId,
          text: payload.text,
        }));
      }
    }
  }

  return events;
}

export class SessionBroadcaster
{
  private readonly m_key: SessionKey;
  private readonly m_storagePaths: StoragePaths;
  private readonly m_persistenceHub: SessionPersistenceHub;
  private readonly m_clients = new Map<string, ConnectedClient>();
  private readonly m_unsubscribePersistedEnvelope: () => void;

  constructor(options: SessionBroadcasterOptions)
  {
    this.m_key = options.key;
    this.m_storagePaths = options.storagePaths;
    this.m_persistenceHub = options.persistenceHub;
    this.m_unsubscribePersistedEnvelope = this.m_persistenceHub.Subscribe((envelope) =>
    {
      this.Broadcast(envelope);
    });
  }

  get Key(): SessionKey
  {
    return this.m_key;
  }

  get ClientCount(): number
  {
    return this.m_clients.size;
  }

  get LatestSequence(): number
  {
    return this.m_persistenceHub.LatestSequence;
  }

  async HistoryWindow(): Promise<HistoryWindow>
  {
    return this.m_persistenceHub.HistoryWindow();
  }

  RegisterClient(socket: WebSocket, clientId?: string): ConnectedClient
  {
    const connectionId = randomUUID();

    return {
      connectionId,
      socket,
      clientId,
    };
  }

  ActivateClient(client: ConnectedClient): void
  {
    this.m_clients.set(client.connectionId, client);
  }

  RemoveClient(connectionId: string): void
  {
    this.m_clients.delete(connectionId);
  }

  SendDirect(connectionId: string, envelope: ChatEnvelope): void
  {
    const client = this.m_clients.get(connectionId);

    if (client === undefined)
    {
      return;
    }

    SendEnvelope(client.socket, envelope);
  }

  Broadcast(envelope: ChatEnvelope): void
  {
    for (const client of this.m_clients.values())
    {
      SendEnvelope(client.socket, envelope);
    }
  }

  async ReplayAfter(
    client: ConnectedClient,
    after: number,
    throughSequence = Number.MAX_SAFE_INTEGER,
  ): Promise<void>
  {
    const entries = await CollectSessionLogEntries(
      this.m_storagePaths,
      this.m_key.pile,
      this.m_key.sessionId,
    );

    for (const entry of entries)
    {
      if (entry.sequence > after && entry.sequence <= throughSequence)
      {
        SendEnvelope(client.socket, entry.envelope);
      }
    }
  }

  async HandleUserMessage(
    connectionId: string,
    payload: ClientUserMessagePayload,
  ): Promise<void>
  {
    await this.m_persistenceHub.HandleUserMessage(payload);
  }

  async HandleHistoryRequest(
    connectionId: string,
    requestId: string,
    request: ClientHistoryRequestPayload,
  ): Promise<void>
  {
    const pagePromise = ReadHistoryPage(
      this.m_storagePaths,
      this.m_key.pile,
      this.m_key.sessionId,
      request as HistoryPageRequest,
    );

    const page = await pagePromise;
    const prefer = request.prefer ?? "snapshots";
    const events = ExtractAguiEvents(page.envelopes);
    const payload: Record<string, unknown> = {
      requestId,
      direction: page.direction,
      oldestSequence: page.oldestSequence,
      newestSequence: page.newestSequence,
      hasMoreBefore: page.hasMoreBefore,
      hasMoreAfter: page.hasMoreAfter,
    };

    if (prefer === "snapshots")
    {
      payload.messages = eventsToSnapshots(events);
      payload.events = [];
    }
    else
    {
      payload.events = events;
      payload.messages = [];
    }

    const envelope = CreateChatEnvelope({
      kind: x_historyPageKind,
      pile: this.m_key.pile,
      sessionId: this.m_key.sessionId,
      payload,
    });

    this.SendDirect(connectionId, envelope);
  }

  RecordAck(connectionId: string, sequence: number): void
  {
    const client = this.m_clients.get(connectionId);

    if (client === undefined)
    {
      return;
    }

    client.lastAckSequence = sequence;
  }

  Dispose(): void
  {
    this.m_unsubscribePersistedEnvelope();
    this.m_clients.clear();
  }
}

export class SessionBroadcasterRegistry
{
  private readonly m_broadcasters = new Map<string, SessionBroadcaster>();

  async GetOrCreate(options: SessionBroadcasterOptions): Promise<SessionBroadcaster>
  {
    const encodedKey = FormatSessionKey(options.key);
    let broadcaster = this.m_broadcasters.get(encodedKey);

    if (broadcaster === undefined)
    {
      broadcaster = new SessionBroadcaster(options);
      this.m_broadcasters.set(encodedKey, broadcaster);
    }

    return broadcaster;
  }

  Get(key: SessionKey): SessionBroadcaster | undefined
  {
    return this.m_broadcasters.get(FormatSessionKey(key));
  }

  Remove(key: SessionKey): void
  {
    const encodedKey = FormatSessionKey(key);
    const broadcaster = this.m_broadcasters.get(encodedKey);

    if (broadcaster !== undefined)
    {
      broadcaster.Dispose();
      this.m_broadcasters.delete(encodedKey);
    }
  }

  ReleaseIfIdle(key: SessionKey): void
  {
    const broadcaster = this.Get(key);

    if (broadcaster === undefined || broadcaster.ClientCount > 0)
    {
      return;
    }

    this.Remove(key);
  }

  Dispose(): void
  {
    for (const broadcaster of this.m_broadcasters.values())
    {
      broadcaster.Dispose();
    }

    this.m_broadcasters.clear();
  }
}

