const x_replaceEditSchema = Type.Object({
  oldText: Type.String({
    description:
      "Exact text for one targeted replacement. It must be unique in the original file and must not overlap with any other edits[].oldText in the same call.",
  }),
  newText: Type.String({ description: "Replacement text for this targeted edit." }),
}, { additionalProperties: false });

const x_editSchema = Type.Object({
  path: Type.String({ description: "Path to the file to edit (relative or absolute)" }),
  edits: Type.Array(x_replaceEditSchema, {
    description:
      "One or more targeted replacements. Each edit is matched against the original file, not incrementally.",
  }),
}, { additionalProperties: false });

function PrepareEditArguments(input: Record<string, unknown>): Record<string, unknown>
{
  if (typeof input.edits === "string")
  {
    try
    {
      const parsed = JSON.parse(input.edits);

      if (Array.isArray(parsed))
      {
        input.edits = parsed;
      }
    }
    catch
    {
    }
  }

  if (
    typeof input.oldText === "string" &&
    typeof input.newText === "string"
  )
  {
    const edits = Array.isArray(input.edits) ? [...input.edits] : [];
    edits.push({ oldText: input.oldText, newText: input.newText });
    const { oldText: _oldText, newText: _newText, ...rest } = input;
    return { ...rest, edits };
  }

  return input;
}

function ValidateEditInput(input: Record<string, unknown>): { path: string; edits: EditReplacement[] }
{
  if (!Array.isArray(input.edits) || input.edits.length === 0)
  {
    throw new Error("Edit tool input is invalid. edits must contain at least one replacement.");
  }

  const edits: EditReplacement[] = [];

  for (const entry of input.edits)
  {
    if (
      typeof entry !== "object" ||
      entry === null ||
      typeof (entry as EditReplacement).oldText !== "string" ||
      typeof (entry as EditReplacement).newText !== "string"
    )
    {
      throw new Error("Edit tool input is invalid. Each edit must include oldText and newText.");
    }

    edits.push({
      oldText: (entry as EditReplacement).oldText,
      newText: (entry as EditReplacement).newText,
    });
  }

  return { path: String(input.path ?? ""), edits };
}

export function CreateEditTool(context: ScopedToolContext): ScopedToolDefinition
{
  return {
    name: "edit",
    label: "edit",
    description:
      "Edit a single file under the session root using exact text replacement. Every edits[].oldText must match a unique, non-overlapping region of the original file.",
    parameters: x_editSchema,
    async execute(_toolCallId, params, signal)
    {
      if (signal?.aborted)
      {
        return ToolError("Operation aborted");
      }

      let validated: { path: string; edits: EditReplacement[] };

      try
      {
        validated = ValidateEditInput(PrepareEditArguments(params));
      }
      catch (error)
      {
        return ToolError(error instanceof Error ? error.message : String(error));
      }

      let absolutePath: string;

      try
      {
        absolutePath = await ResolveScopedPath(context.policy, validated.path);
      }
      catch (error)
      {
        const escapeResult = HandlePathEscape(context, "edit", error);

        if (escapeResult)
        {
          return escapeResult;
        }

        throw error;
      }

      const displayPath = RelativizeDisplayPath(context.policy, absolutePath);

      try
      {
        await access(absolutePath, constants.R_OK | constants.W_OK);
      }
      catch (error)
      {
        const errorMessage =
          error instanceof Error && "code" in error
            ? `Error code: ${String((error as NodeJS.ErrnoException).code)}`
            : String(error);
        return ToolError(`Could not edit file: ${displayPath}. ${errorMessage}.`);
      }

      try
      {
        const buffer = await readFile(absolutePath);
        const rawContent = buffer.toString("utf-8");
        const { bom, text: content } = StripBom(rawContent);
        const originalEnding = DetectLineEnding(content);
        const normalizedContent = NormalizeToLf(content);
        const { newContent } = ApplyEditsToNormalizedContent(
          normalizedContent,
          validated.edits,
          displayPath,
        );
        const finalContent = bom + RestoreLineEndings(newContent, originalEnding);
        await writeFile(absolutePath, finalContent, "utf-8");

        return ToolSuccess(
          `Successfully replaced ${validated.edits.length} block(s) in ${displayPath}.`,
          { path: displayPath, edits: validated.edits.length },
        );
      }
      catch (error)
      {
        return ToolError(error instanceof Error ? error.message : String(error));
      }
    },
  };
}

import { constants } from "node:fs";
import { access, lstat, readdir, stat } from "node:fs/promises";
import path from "node:path";

import { Type } from "typebox";

import { RelativizeDisplayPath } from "../results.js";
import type { ScopedToolContext, ScopedToolDefinition } from "../types.js";
import {
  HandlePathEscape,
  ResolveScopedPath,
  ToolError,
  ToolSuccess,
  x_treeDefaultIgnores,
} from "../toolHelpers.js";

const x_treeSchema = Type.Object({
  path: Type.Optional(Type.String({ description: "Directory to tree (default: session root)" })),
  maxDepth: Type.Optional(Type.Number({ description: "Maximum directory depth (default: 4)" })),
  maxEntries: Type.Optional(Type.Number({ description: "Maximum total entries (default: 200)" })),
});

const x_defaultMaxDepth = 4;
const x_defaultMaxEntries = 200;

interface TreeWalkState
{
  lines: string[];
  entryCount: number;
  truncated: boolean;
}

function ShouldIgnoreDirectory(name: string): boolean
{
  return x_treeDefaultIgnores.includes(name);
}

async function WalkTree(
  policy: ScopedToolContext["policy"],
  absoluteDirectory: string,
  prefix: string,
  depth: number,
  maxDepth: number,
  maxEntries: number,
  state: TreeWalkState,
): Promise<void>
{
  if (state.entryCount >= maxEntries)
  {
    state.truncated = true;
    return;
  }

  if (depth > maxDepth)
  {
    return;
  }

  const entries = await readdir(absoluteDirectory, { withFileTypes: true });
  entries.sort((left, right) => left.name.localeCompare(right.name));

  for (const entry of entries)
  {
    if (state.entryCount >= maxEntries)
    {
      state.truncated = true;
      return;
    }

    const entryAbsolute = path.join(absoluteDirectory, entry.name);
    policy.AssertWithinRoot(entryAbsolute);
    const entryStat = await lstat(entryAbsolute);

    if (entryStat.isSymbolicLink())
    {
      continue;
    }

    const entryRelative = RelativizeDisplayPath(policy, entryAbsolute);

    if (entryStat.isDirectory() && ShouldIgnoreDirectory(entry.name))
    {
      continue;
    }

    const marker = entryStat.isDirectory() ? "/" : "";
    state.lines.push(`${prefix}${entryRelative}${marker}`);
    state.entryCount += 1;

    if (entryStat.isDirectory())
    {
      await WalkTree(
        policy,
        entryAbsolute,
        `${prefix}  `,
        depth + 1,
        maxDepth,
        maxEntries,
        state,
      );
    }
  }
}

export function CreateTreeTool(context: ScopedToolContext): ScopedToolDefinition
{
  return {
    name: "tree",
    label: "tree",
    description:
      "Return a bounded directory tree under the session root with default ignores for VCS, dependency, build, cache, and generated directories.",
    parameters: x_treeSchema,
    async execute(_toolCallId, params, signal)
    {
      if (signal?.aborted)
      {
        return ToolError("Operation aborted");
      }

      const pathArg = typeof params.path === "string" ? params.path : ".";
      const maxDepth = typeof params.maxDepth === "number" ? params.maxDepth : x_defaultMaxDepth;
      const maxEntries = typeof params.maxEntries === "number" ? params.maxEntries : x_defaultMaxEntries;

      let absolutePath: string;

      try
      {
        absolutePath = await ResolveScopedPath(context.policy, pathArg);
      }
      catch (error)
      {
        const escapeResult = HandlePathEscape(context, "tree", error);

        if (escapeResult)
        {
          return escapeResult;
        }

        throw error;
      }

      const displayPath = RelativizeDisplayPath(context.policy, absolutePath);

      try
      {
        await access(absolutePath, constants.R_OK);
      }
      catch
      {
        return ToolError(`Path not found: ${displayPath}`);
      }

      const directoryStat = await stat(absolutePath);

      if (!directoryStat.isDirectory())
      {
        return ToolError(`Not a directory: ${displayPath}`);
      }

      const state: TreeWalkState = {
        lines: [displayPath],
        entryCount: 1,
        truncated: false,
      };

      await WalkTree(
        context.policy,
        absolutePath,
        "",
        1,
        maxDepth,
        maxEntries,
        state,
      );

      let output = state.lines.join("\n");

      if (state.truncated)
      {
        output += `\n\n[Truncated: reached maxEntries=${maxEntries}.]`;
      }

      return ToolSuccess(output, {
        path: displayPath,
        entryCount: state.entryCount,
        truncated: state.truncated,
      });
    },
  };
}

