type Listener = (event: Record<string, unknown>) => void;

class FakeElement
{
  public readonly tagName: string;
  public readonly nodeName: string;
  public className = "";
  public readonly dataset: Record<string, string> = {};
  public readonly style: Record<string, string> = {};
  public readonly children: FakeElement[] = [];
  public parentNode: FakeElement | null = null;
  public type = "";
  public id = "";
  public name = "";
  public value = "";
  public required = false;
  public autocomplete = "";
  public htmlFor = "";
  public rows = 0;
  public placeholder = "";
  public disabled = false;
  public selected = false;
  public scrollHeight = 0;
  public scrollTop = 0;
  public clientHeight = 0;
  private x_textContent = "";
  private x_innerHTML = "";
  private readonly x_listeners: Record<string, Listener[]> = {};

  public readonly classList = {
    add: (...names: string[]): void => {
      const existing = this.x_ClassNames();
      for (const name of names) {
        if (!existing.includes(name)) {
          existing.push(name);
        }
      }
      this.className = existing.join(" ");
    },
    remove: (...names: string[]): void => {
      this.className = this.x_ClassNames()
        .filter((name) => !names.includes(name))
        .join(" ");
    },
    contains: (name: string): boolean => this.x_ClassNames().includes(name),
    toggle: (name: string, force?: boolean): boolean => {
      const shouldAdd = force == null ? !this.classList.contains(name) : force;
      if (shouldAdd) {
        this.classList.add(name);
      } else {
        this.classList.remove(name);
      }
      return shouldAdd;
    },
  };

  public constructor(tagName: string, className?: string)
  {
    this.tagName = tagName.toUpperCase();
    this.nodeName = this.tagName;
    this.className = className || "";
  }

  public get childNodes(): FakeElement[]
  {
    return this.children;
  }

  public get textContent(): string
  {
    if (this.children.length > 0) {
      return this.x_textContent + this.children.map((child) => child.textContent).join("");
    }
    return this.x_textContent;
  }

  public set textContent(value: string)
  {
    for (const child of this.children) {
      child.parentNode = null;
    }
    this.children.length = 0;
    this.x_textContent = value != null ? String(value) : "";
    this.x_innerHTML = "";
  }

  public get innerHTML(): string
  {
    return this.x_innerHTML;
  }

  public set innerHTML(value: string)
  {
    for (const child of this.children) {
      child.parentNode = null;
    }
    this.children.length = 0;
    this.x_innerHTML = value != null ? String(value) : "";
    this.x_textContent = this.x_innerHTML.replace(/<[^>]*>/g, "");
  }

  public appendChild(child: FakeElement): FakeElement
  {
    if (child.parentNode) {
      child.parentNode.removeChild(child);
    }
    child.parentNode = this;
    this.children.push(child);

    if (this.tagName === "SELECT" && child.tagName === "OPTION") {
      if (child.selected || this.value === "") {
        this.value = child.value;
      }
    }

    if (this.classList.contains("agui-chat-transcript")) {
      this.scrollHeight = Math.max(this.scrollHeight, this.children.length * 500);
    }

    return child;
  }

  public insertBefore(child: FakeElement, referenceNode: FakeElement | null): FakeElement
  {
    if (referenceNode === null) {
      return this.appendChild(child);
    }

    const referenceIndex = this.children.indexOf(referenceNode);
    if (referenceIndex < 0) {
      return this.appendChild(child);
    }

    if (child.parentNode) {
      child.parentNode.removeChild(child);
    }
    child.parentNode = this;
    this.children.splice(referenceIndex, 0, child);

    if (this.classList.contains("agui-chat-transcript")) {
      this.scrollHeight = Math.max(this.scrollHeight, this.children.length * 500);
    }

    return child;
  }

  public removeChild(child: FakeElement): FakeElement
  {
    const index = this.children.indexOf(child);
    if (index >= 0) {
      this.children.splice(index, 1);
      child.parentNode = null;
    }
    return child;
  }

  public addEventListener(type: string, handler: Listener): void
  {
    this.x_listeners[type] = this.x_listeners[type] || [];
    this.x_listeners[type].push(handler);
  }

  public removeEventListener(type: string, handler?: Listener): void
  {
    if (!handler) {
      delete this.x_listeners[type];
      return;
    }
    this.x_listeners[type] = (this.x_listeners[type] || []).filter(
      (entry) => entry !== handler,
    );
  }

  public dispatchEvent(event: Record<string, unknown>): boolean
  {
    const type = String(event.type || "");
    for (const handler of this.x_listeners[type] || []) {
      handler(event);
    }
    return true;
  }

  public click(): void
  {
    this.dispatchEvent({ type: "click" });
  }

  public querySelector(selector: string): FakeElement | null
  {
    return this.querySelectorAll(selector)[0] || null;
  }

  public querySelectorAll(selector: string): FakeElement[]
  {
    const results: FakeElement[] = [];
    const matcher = this.x_CreateMatcher(selector);
    const stack = [...this.children];
    while (stack.length > 0) {
      const node = stack.shift();
      if (!node) {
        continue;
      }
      if (matcher(node)) {
        results.push(node);
      }
      stack.push(...node.children);
    }
    return results;
  }

.agui-chat-root
{
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  background: var(--agui-chat-bg, #0f1419);
  color: var(--agui-chat-text, #e6edf3);
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 14px;
  line-height: 1.45;
}

.agui-chat-status
{
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--agui-chat-border, #2d3a4d);
  background: var(--agui-chat-surface, #1a2332);
  flex-shrink: 0;
}

.agui-chat-status-main
{
  display: flex;
  align-items: center;
  gap: 8px;
}

.agui-chat-status-dot
{
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--agui-chat-muted, #8b9cb3);
  flex-shrink: 0;
}

.agui-chat-status-dot--live
{
  background: var(--agui-chat-live, #22c55e);
}

.agui-chat-status-dot--warning
{
  background: var(--agui-chat-warning, #f59e0b);
}

.agui-chat-status-label
{
  font-size: 13px;
  font-weight: 600;
}

.agui-chat-status-label--warning
{
  color: var(--agui-chat-warning, #f59e0b);
}

.agui-chat-status-count
{
  color: var(--agui-chat-muted, #8b9cb3);
  font-size: 12px;
}

.agui-chat-status-steps
{
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-left: auto;
}

.agui-chat-step-chip
{
  font-size: 11px;
  color: var(--agui-chat-muted, #8b9cb3);
  padding: 2px 8px;
  border-radius: 4px;
  background: var(--agui-chat-surface-muted, #232f3e);
  border: 1px solid var(--agui-chat-border, #2d3a4d);
}

.agui-chat-transcript
{
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 0;
}

.agui-chat-transcript > *
{
  flex-shrink: 0;
}

.agui-chat-bubble
{
  border-radius: 8px;
  padding: 10px 12px;
  max-width: 100%;
  word-break: break-word;
}

.agui-chat-bubble--user
{
  align-self: flex-start;
  background: var(--agui-chat-surface-muted, #232f3e);
  border: 1px solid var(--agui-chat-border, #2d3a4d);
}

.agui-chat-bubble--assistant
{
  align-self: flex-start;
  background: var(--agui-chat-surface, #1a2332);
  border: 1px solid var(--agui-chat-border, #2d3a4d);
}

.agui-chat-bubble--tool,
.agui-chat-bubble--reasoning
{
  align-self: stretch;
  background: var(--agui-chat-surface-muted, #232f3e);
  border: 1px solid var(--agui-chat-border, #2d3a4d);
  padding: 0;
  overflow: hidden;
}

.agui-chat-role
{
  display: block;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--agui-chat-muted, #8b9cb3);
  margin-bottom: 6px;
}

.agui-chat-content
{
  white-space: pre-wrap;
}

.agui-chat-bubble--assistant .agui-chat-content
{
  white-space: normal;
}

.agui-chat-bubble--assistant .agui-chat-content p
{
  margin: 0 0 8px;
}

.agui-chat-bubble--assistant .agui-chat-content p:last-child
{
  margin-bottom: 0;
}

.agui-chat-bubble--user .agui-chat-content
{
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 13px;
}

.agui-chat-inline-code
{
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.9em;
  padding: 1px 5px;
  border-radius: 4px;
  background: var(--agui-chat-surface-muted, #232f3e);
  border: 1px solid var(--agui-chat-border, #2d3a4d);
}

.agui-chat-code-block
{
  margin: 8px 0;
  padding: 10px 12px;
  border-radius: 6px;
  background: var(--agui-chat-bg, #0f1419);
  border: 1px solid var(--agui-chat-border, #2d3a4d);
  overflow-x: auto;
}

.agui-chat-code-block code
{
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  white-space: pre;
}

.agui-chat-streaming
{
  display: inline-block;
  width: 2px;
  height: 1em;
  margin-left: 2px;
  vertical-align: text-bottom;
  background: var(--agui-chat-accent, #3b82f6);
  animation: agui-chat-blink 1s step-end infinite;
}

@keyframes agui-chat-blink
{
  0%, 100%
  {
    opacity: 1;
  }

  50%
  {
    opacity: 0;
  }
}

.agui-chat-activity
{
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 4px 0;
  font-size: 12px;
  color: var(--agui-chat-muted, #8b9cb3);
}

.agui-chat-activity-label
{
  font-weight: 600;
  flex-shrink: 0;
}

